/**
 * Scrapes a website for email addresses
 * 
 * @param {string} websiteUrl - URL of the website to scrape
 * @returns {Promise<{emails: string[], success: boolean}>} 
 *          Object containing extracted emails and success status
 */
async function scrapeWebsite(websiteUrl) {
    try {
        // Fetch the website HTML
        const html = await this.helpers.request({
            method: 'GET',
            url: websiteUrl,
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
            },
            timeout: 15000,
            rejectUnauthorized: false
        });

        // Extract emails from the HTML content
        const emails = extractEmails(html);

        // Also extract mailto: links
        const mailtoRegex = /mailto:([^"'\s<>]+)/gi;
        let match;
        while ((match = mailtoRegex.exec(html)) !== null) {
            const email = match[1].trim();
            if (isValidEmail(email) && !emails.includes(email)) {
                emails.push(email);
            }
        }

        return {
            emails: [...new Set(emails)],
            success: true
        };

    } catch (error) {
        return {
            emails: [],
            success: false
        };
    }
}

