            keywordCity: workflowContext.keywordCity || '',
            keywordIndustry: workflowContext.keywordIndustry || '',
            keywordIntent: workflowContext.keywordIntent || '',
            executionId: workflowContext.executionId || '',
            totalProcessed: processedCount,
            success: true,
